import json, pathlib
from collections import defaultdict
p=pathlib.Path('orders')
totals=defaultdict(int)
malformed=[]
for f in sorted(p.iterdir()):
    if not f.is_file():
        continue
    try:
        d=json.loads(f.read_text())
    except (json.JSONDecodeError, UnicodeDecodeError):
        malformed.append(f.name)
        continue
    cat=d['category']
    if cat != 'refund':
        totals[cat]+=d['amount_cents']
summary={'totals':dict(sorted(totals.items())),'malformed':malformed}
pathlib.Path('summary.json').write_text(json.dumps(summary, indent=2)+'\n')
print(json.dumps(summary, indent=2))
PY
